<?php require_once __DIR__ . '/_boot.php'; $rows=[]; try { $st=db()->prepare("SELECT ps.*, uo.name opened_name, uc.name closed_name FROM pos_shifts ps LEFT JOIN users uo ON uo.id=ps.opened_by LEFT JOIN users uc ON uc.id=ps.closed_by WHERE ps.branch_id=? ORDER BY ps.id DESC LIMIT 200"); $st->execute([$unitId]); $rows=$st->fetchAll(PDO::FETCH_ASSOC)?:[]; } catch(Throwable $e) { $err=$e->getMessage(); } ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Laporan Shift Dapur</title><link rel="icon" href="<?php echo e(favicon_url()); ?>"><link rel="stylesheet" href="<?php echo e(asset_url('assets/app.css')); ?>"><style><?php echo $customCss; ?></style></head><body><div class="container"><?php include __DIR__ . '/_sidebar.php'; ?><div class="main"><div class="topbar"><button class="btn" data-toggle-sidebar type="button">Menu</button><strong>Laporan Shift Dapur</strong></div><div class="content"><div class="card"><table class="table"><thead><tr><th>Kode</th><th>Status</th><th>Buka</th><th>Tutup</th><th>Kas Awal</th><th>Kas Aktual</th><th>Selisih</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?php echo e($r['shift_code']); ?></td><td><?php echo e($r['status']); ?></td><td><?php echo e($r['opened_at']); ?><br><small><?php echo e($r['opened_name'] ?? '-'); ?></small></td><td><?php echo e($r['closed_at'] ?? '-'); ?><br><small><?php echo e($r['closed_name'] ?? '-'); ?></small></td><td><?php echo e(format_money($r['opening_cash_actual'])); ?></td><td><?php echo e(format_money($r['counted_cash_total'] ?? 0)); ?></td><td><?php echo e(format_money($r['cash_difference'] ?? 0)); ?></td></tr><?php endforeach; if(empty($rows)): ?><tr><td colspan="7">Belum ada shift.</td></tr><?php endif; ?></tbody></table></div></div></div></div><script src="<?php echo e(asset_url('assets/app.js')); ?>"></script></body></html>
